-- River Hub: parish census population + system base population P
-- Generated by scripts/estimate_system_population.py. Idempotent; re-run to refresh.
begin;
create temp table _oa (code text primary key, pop int, geom geometry(Point,4326)) on commit drop;

update parishes p set census_2021_population = sub.pop
from (
  select pa.id, coalesce(sum(o.pop),0) as pop
  from parishes pa
  join _oa o on ST_Contains(pa.boundary, o.geom)
  where pa.boundary is not null
  group by pa.id
) sub
where p.id = sub.id;

select s.id, s.organisation_id,
  (select coalesce(sum(pp.census_2021_population),0)::int
     from (
       select distinct p.id, p.census_2021_population
       from parishes p
       join sewage_assets a
         on a.sewage_system_id = s.id
        and a.latitude is not null and a.longitude is not null
        and ST_Contains(p.boundary, ST_SetSRID(ST_Point(a.longitude,a.latitude),4326))
       where p.census_2021_population is not null
     ) pp),
  now(), 'ONS Census 2021 OA->parish best-fit centroid (River Teign bbox)'
from sewage_systems s
on conflict (system_id) do update
  -- only overwrite when the recompute produced a positive population, so a system whose assets
  -- don't currently match a census parish keeps its previously-estimated value instead of being
  -- zeroed. population_override is never touched here.
  set ons_population    = case when excluded.ons_population > 0
                               then excluded.ons_population else system_assumptions.ons_population end,
      ons_calculated_at = case when excluded.ons_population > 0
                               then excluded.ons_calculated_at else system_assumptions.ons_calculated_at end,
      ons_source        = case when excluded.ons_population > 0
                               then excluded.ons_source else system_assumptions.ons_source end;
commit;
